cardCss:
.chenyu-card {
    background: var(--card-bg, #fbf6ea);
    border-radius: 14px;
    padding: 20px 22px;
    box-shadow: 0 1px 3px rgba(80,60,30,.12), 0 8px 22px rgba(80,60,30,.10);
    border: 1px solid var(--line, #e4d9bf);
    min-height: 280px;
    display: flex; gap: 16px;
    font-family: "Songti SC","STSong","SimSun","Noto Serif SC",serif;
}
.chenyu-seal {
    flex-shrink: 0;
    writing-mode: vertical-rl; text-orientation: upright;
    background: #9b2d20; color: #fbf6ea;
    font-weight: 700;
    font-size: calc(18px * var(--card-font-scale,1));
    letter-spacing: 6px;
    padding: 12px 8px; border-radius: 8px;
    box-shadow: inset 0 0 0 2px rgba(251,246,234,.35);
    align-self: flex-start;
}
.chenyu-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.chenyu-text {
    font-weight: var(--card-font-weight, 700);
    font-size: calc(30px * var(--card-font-scale,1));
    line-height: 1.6; color: #2b2620;
    margin: 4px 0 10px;
}
.chenyu-source {
    font-size: calc(14px * var(--card-font-scale,1));
    color: #8a6d3b; font-style: italic;
    margin-bottom: 8px;
}
.chenyu-gloss {
    font-size: calc(15px * var(--card-font-scale,1));
    line-height: 1.75; color: #4a4034;
    border-top: 1px dashed var(--line, #e4d9bf);
    padding-top: 10px; margin-top: auto;
}
.chenyu-tools { display: flex; gap: 6px; margin-top: 12px; }
.chenyu-tools .action-btn { width: 38px; height: 38px; border: none; background: var(--action-btn-bg, #efe6d2); border-radius: 90px; cursor: pointer; display: flex; align-items: center; justify-content: center; color: #9b2d20; transition: all .2s; }
.chenyu-tools .action-btn:hover { background: #e2d4b5; }
.chenyu-tools .action-btn.is-active { background: #9b2d20; color: #fbf6ea; }

.action-btn i { font-size: 18px; line-height: 1; }
.action-btn:hover i { transform: scale(1.1); }

.chenyu-card { margin-bottom: 16px; }

.chenyu-card { flex-direction: column; }
.chenyu-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; margin-bottom: 12px; }
.chenyu-tools { margin-top: 0; }

cardJs:
(function () {
    'use strict';
    function esc(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    window.cardTemplate = {
        name: '中国古代谶语录',
        fields: [
            { key: 'dynasty', label: '朝代', hideable: false },
            { key: 'text',   label: '原文', hideable: false },
            { key: 'source', label: '出处' },
            { key: 'gloss',  label: '考据' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(k) { return hidden.has && hidden.has(k); }
            function wrap(k, html) { return isHidden(k) ? '' : html; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            var favActive = data.is_favorite === 1 ? 'is-active' : '';
            return '<div class="chenyu-card" data-card-id="' + data.id + '">' +
                '<div class="chenyu-head">' +
                    wrap('dynasty', '<div class="chenyu-seal">' + esc(d.dynasty) + '</div>') +
                    '<div class="chenyu-tools">' +
                        '<button class="action-btn act-play" data-action="play" data-tooltip="朗读"><i class="fa-solid fa-volume-high"></i></button>' +
                        '<button class="action-btn act-mark ' + markActive + '" data-action="mark" data-tooltip="标记"><i class="' + (data.is_unknown === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>' +
                        '<button class="action-btn act-fav ' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-bookmark"></i></button>' +
                    '</div>' +
                '</div>' +
                '<div class="chenyu-main">' +
                    wrap('text', '<div class="chenyu-text">' + esc(d.text) + '</div>') +
                    wrap('source', '<div class="chenyu-source">出处：' + esc(d.source) + '</div>') +
                    wrap('gloss', '<div class="chenyu-gloss">' + esc(d.gloss) + '</div>') +
                '</div>' +
            '</div>';
        },
        init: function (el, cardData, api) {
            api.track('definition_view');
            var playBtn = el.querySelector('[data-action="play"]');
            if (playBtn) playBtn.addEventListener('click', function () {
                var d = (cardData && cardData.data) || {};
                api.playAudio(d.text || '');
                api.track('audio_play');
            });
            var markBtn = el.querySelector('[data-action="mark"]');
            if (markBtn) markBtn.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var favBtn = el.querySelector('[data-action="favorite"]');
            if (favBtn) favBtn.addEventListener('click', function () {
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
        }
    };
})();
